<section class="aicard"><div class="row g8 fw5"><i class="ic ic-sm i-ai" aria-hidden="true"></i>AI summary and next step</div><div class="demo" id="tk-summary"><?= $t['summary'] !== '' ? nl2br(h($t['summary'])) : ($d['copilot'] && $d['aiReady'] ? 'No summary yet. Refresh to write one from the conversation.' : 'AI summaries need a provider key. Set it up in the <a href="' . sl_route('AiCenter') . '">AI centre</a>.') ?></div><div class="row g8"><button class="sl-btn ghost sm" type="button" data-sl-copy="<?= h($t['summary']) ?>">Copy</button><?php if ($d['copilot'] && $d['aiReady']): ?><button class="sl-btn ghost sm" type="button" id="tk-ai-summary">Refresh</button><?php endif; ?></div></section>
<section class="sl-card col g8"><h2 class="sl-ct">To do on this ticket</h2><?php foreach ($d['tasks'] as $task): $done = !empty($task['done_at']) || !empty($task['done']); ?><div class="tk-check"><span class="sl-chk <?= $done ? 'on' : '' ?>" role="checkbox" aria-checked="<?= $done ? 'true' : 'false' ?>" data-cs-action="task_done" data-p-task_id="<?= (int) $task['id'] ?>" data-p-done="<?= $done ? 0 : 1 ?>" data-cs-reload></span><span class="<?= $done ? 'mut' : '' ?>" <?= $done ? 'style="text-decoration:line-through"' : '' ?>><?= h($task['title']) ?></span><?php if (!empty($task['due_at'])): ?><span class="mut" style="font-size:11.5px;margin-left:auto"><?= h(sl_date($task['due_at'], 'M j')) ?></span><?php endif; ?></div><?php endforeach; ?><button class="au-add" type="button" style="height:30px;padding:0 10px;border-radius:8px;border:1px dashed var(--line-2);background:transparent;font-size:12.5px;align-self:flex-start" data-cs-action="task" data-p-id="<?= (int) $t['id'] ?>" data-cs-prompt="What needs doing?" data-cs-prompt-key="title" data-cs-reload>+ Add step</button></section>
<section class="sl-card col g8"><h2 class="sl-ct">Similar tickets</h2><?php foreach ($d['similar'] as $s): ?><div class="tk-mini"><span class="mono mut"><?= h($s['ref'] ?? '') ?></span><a class="grow" href="<?= h(sl_route('CsTicket', ['id' => $s['id']])) ?>" style="color:inherit"><?= h($s['subject'] ?? '') ?></a><span class="ov-pill <?= in_array($s['status'] ?? '', ['resolved', 'closed'], true) ? 'ok' : 'warn' ?>"><?= h(cdp_csStatuses()[$s['status'] ?? ''] ?? '') ?></span></div><?php endforeach; ?><?php if (!$d['similar']): ?><span class="mut sm">No other open tickets from this customer.</span><?php endif; ?><?php foreach ($d['kb'] as $a): ?><a class="sm fw5" href="<?= h(sl_route('CsPlaybook', ['kb' => $a['id']])) ?>">Help article: <?= h($a['title']) ?></a><?php endforeach; ?></section>
<section class="sl-card col g8"><h2 class="sl-ct">Tags and fields</h2><div class="row wrap g6"><?php foreach ($d['tags'] as $tg): ?><span class="tg"><i class="ic ic-sm i-hash" aria-hidden="true"></i><?= h($tg) ?> <button type="button" class="sl-ib" style="width:16px;height:16px" aria-label="Remove tag" data-cs-action="tag" data-p-id="<?= (int) $t['id'] ?>" data-p-tag="<?= h($tg) ?>" data-p-remove="1" data-cs-reload><i class="ic ic-sm i-x" aria-hidden="true"></i></button></span><?php endforeach; ?><button class="tg off" type="button" data-cs-action="tag" data-p-id="<?= (int) $t['id'] ?>" data-cs-prompt="Tag to add" data-cs-prompt-key="tag" data-cs-reload><i class="ic ic-sm i-plus" aria-hidden="true"></i>Add tag</button></div><div class="tk-kv"><span>Channel</span><span><?= h($t['channelLabel']) ?></span><span>Language</span><label class="row g6"><select data-tk-field="language" aria-label="Language" class="sl-in" style="height:28px;padding:0 6px;font-size:12.5px"><?php foreach ($d['languages'] as $k => $l): ?><option value="<?= h($k) ?>" <?= $k === $t['language'] ? 'selected' : '' ?>><?= h($l) ?></option><?php endforeach; ?></select><?= $t['languageSource'] === 'ai' ? '<span class="mut" style="font-size:11px">detected</span>' : '' ?></label><span>Reference</span><span class="mono"><?= h($t['ref']) ?></span><span>Followers</span><span><?= $d['followers'] ? h(implode(', ', array_map(fn($f) => $f['name'] ?? '', $d['followers']))) : '—' ?></span><?php if ($t['csat'] !== null): ?><span>Rating</span><span><?= (int) $t['csat'] ?> / 5</span><?php endif; ?></div><?php if ($d['isAdmin']): ?><div class="row g6" style="margin-top:4px"><button class="sl-btn ghost sm" type="button" data-tk-field="disposition" data-value="archived">Archive</button><button class="sl-btn ghost sm" type="button" data-tk-field="disposition" data-value="spam">Spam</button><button class="sl-btn ghost sm" type="button" data-tk-field="disposition" data-value="trash" data-sl-confirm="Move this ticket to trash?">Trash</button></div><?php endif; ?></section>
</aside></div>
<div class="sl-dialog" id="tk-resolve" hidden><form class="sl-modal" id="tk-resolve-form" role="dialog" aria-label="Resolve ticket"><div class="row g10"><span class="sl-tile" style="background:var(--green-bg);color:var(--green-ink)"><i class="ic i-check" aria-hidden="true"></i></span><div class="col grow"><b class="fw5">Resolve <?= h($t['ref']) ?></b><span class="mut sm">The customer is asked for a rating <?= (int) cdp_csSetting('csat_delay_min', '60') ?> min later, unless the ticket reopens first.</span></div></div><label class="sl-field"><span class="sl-lab">How was it resolved?</span><label class="sl-sel native"><select name="resolution_code"><?php foreach ($d['resolutionCodes'] as $k => $l): ?><option value="<?= h($k) ?>"><?= h($l) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></label></label><label class="sl-field"><span class="sl-lab">In a sentence</span><textarea class="sl-in" name="resolution_summary" rows="2" required><?= h($t['resolution']) ?></textarea></label><div class="row g8"><button type="submit" class="sl-btn"><i class="ic ic-sm i-check" aria-hidden="true"></i>Resolve</button><button type="button" class="sl-btn ghost" data-sl-close>Cancel</button></div></form></div>
<div class="sl-dialog" id="tk-escalate" hidden><form class="sl-modal" data-cs-form="proposal_create" data-cs-reload role="dialog" aria-label="Escalate"><input type="hidden" name="id" value="<?= (int) $t['id'] ?>"><div class="row g10"><span class="sl-tile" style="background:var(--amber-bg);color:var(--amber-ink)"><i class="ic i-alert" aria-hidden="true"></i></span><div class="col grow"><b class="fw5">Ask an administrator to approve</b><span class="mut sm">Refunds, waivers, claims and account changes are decided by an administrator and then made on their own page.</span></div></div><label class="sl-field"><span class="sl-lab">What needs approval</span><label class="sl-sel native"><select name="kind"><?php foreach ($d['proposalKinds'] as $k => $l): ?><option value="<?= h($k) ?>"><?= h($l) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></label></label><label class="sl-field"><span class="sl-lab">Amount (optional)</span><input class="sl-in" name="amount"></label><label class="sl-field"><span class="sl-lab">Why</span><textarea class="sl-in" name="summary" rows="3" required></textarea></label><div class="row g8"><button type="submit" class="sl-btn">Send for approval</button><button type="button" class="sl-btn ghost" data-sl-close>Cancel</button></div></form></div>
<script>window.CS_CANNED = <?= json_encode(array_map(fn($c) => ['id' => $c['id'], 'title' => $c['title'], 'body' => $c['body'], 'shortcut' => $c['shortcut']], $d['canned']), JSON_HEX_TAG | JSON_HEX_AMP | JSON_UNESCAPED_UNICODE) ?>;</script>
